// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 funding, uint256 value) public {
        // Admissible domain: contract funded with `funding`, owner withdraws a
        // strictly partial amount value < funding. The receiving owner (this
        // test contract) accepts ETH so the reference's transfer always succeeds.
        vm.deal(address(c), funding);
        if (funding == 0) {
            funding = 1;
            vm.deal(address(c), funding);
        }
        value = bound(value, 0, funding - 1);

        vm.prank(address(this)); // owner set in setUp is msg.sender of setUp
        c.withdraw(value);

        // Reference: only `value` leaves the contract; mutant: entire balance leaves.
        assertTrue(address(c).balance == funding - value);
    }

    receive() external payable {}
}
